 62	package br.com.marealte.controller;
 63	
 64	import br.com.marealte.dto.CreateReservationRequest;
 65	import br.com.marealte.dto.ErrorResponse;
 66	import br.com.marealte.model.*;
 67	import br.com.marealte.repository.MessageRepository;
 68	import br.com.marealte.repository.ReservationRepository;
 69	import br.com.marealte.repository.RoomRepository;
 70	import br.com.marealte.service.DocumentService;
 71	import br.com.marealte.service.EmailService;
 72	import br.com.marealte.service.PricingService;
 73	import io.javalin.http.Context;
 74	import java.math.BigDecimal;
 75	import java.time.LocalDate;
 76	
 77	public class ReservationController {
 78	
 79	    private final ReservationRepository reservationRepository;
 80	    private final RoomRepository roomRepository;
 81	    private final EmailService emailService;
 82	
 83	    public ReservationController(ReservationRepository reservationRepository,
 84	                                  RoomRepository roomRepository,
 85	                                  MessageRepository messageRepository) {
 86	        this.reservationRepository = reservationRepository;
 87	        this.roomRepository = roomRepository;
 88	        this.emailService = new EmailService(messageRepository);
 89	    }
 90	
 91	    public void createReservation(Context ctx) {
 92	        try {
 93	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 94	
 95	            if (!validateRequest(request, ctx)) {
 96	                return;
 97	            }
 98	
 99	            if (!validateIdentification(request, ctx)) {
100	                return;
101	            }
102	
103	            Room room = roomRepository.findByNumber(request.getRoomNumber());
104	            if (room == null) {
105	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
106	                return;
107	            }
108	
109	            if (request.getCheckOut() == null || !request.getCheckOut().isAfter(request.getCheckIn())) {
110	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
111	                return;
112	            }
113	
114	            if (request.getGuests() < 1) {
115	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "At least one guest is required"));
116	                return;
117	            }
118	
119	            if (request.getGuests() > room.getCapacity()) {
120	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Room capacity exceeded"));
121	                return;
122	            }
123	
124	            if (!reservationRepository.isRoomAvailable(request.getRoomNumber(), request.getCheckIn(), request.getCheckOut(), null)) {
125	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
126	                return;
127	            }
128	
129	            Reservation reservation = new Reservation();
130	            reservation.setRoomNumber(request.getRoomNumber());
131	            reservation.setGuestName(request.getGuestName());
132	            reservation.setGuestEmail(request.getGuestEmail());
133	            reservation.setGuestCpf(request.getGuestCpf());
134	            reservation.setCompanyCnpj(request.getCompanyCnpj());
135	            reservation.setCompanyName(request.getCompanyName());
136	            reservation.setGuestPassport(request.getGuestPassport());
137	            reservation.setGuestCountry(request.getGuestCountry());
138	            reservation.setCheckIn(request.getCheckIn());
139	            reservation.setCheckOut(request.getCheckOut());
140	            reservation.setGuests(request.getGuests());
141	            reservation.setRatePlan(request.getRatePlan());
142	
143	            calculatePrices(reservation, room);
144	
145	            reservation.setStatus(ReservationStatus.PENDING);
146	            reservation.setAmountPaid(BigDecimal.ZERO);
147	
148	            reservationRepository.save(reservation);
149	
150	            ctx.status(201).json(reservation);
151	
152	        } catch (Exception e) {
153	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
154	        }
155	    }
156	
157	    public void getReservation(Context ctx) {
158	        try {
159	            Long id = Long.parseLong(ctx.pathParam("id"));
160	            Reservation reservation = reservationRepository.findById(id);
161	
162	            if (reservation == null) {
163	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
164	                return;
165	            }
166	
167	            ctx.json(reservation);
168	        } catch (NumberFormatException e) {
169	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
170	        }
171	    }
172	
173	    public void confirmReservation(Context ctx) {
174	        try {
175	            Long id = Long.parseLong(ctx.pathParam("id"));
176	            Reservation reservation = reservationRepository.findById(id);
177	
178	            if (reservation == null) {
179	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
180	                return;
181	            }
182	
183	            if (reservation.getStatus() != ReservationStatus.PENDING) {
184	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed"));
185	                return;
186	            }
187	
188	            reservation.setStatus(ReservationStatus.CONFIRMED);
189	            reservation.setAmountPaid(reservation.getTotal());
190	            reservationRepository.update(reservation);
191	
192	            RoomType roomType = reservationRepository.getRoomType(reservation.getRoomNumber());
193	            Document document = DocumentService.generateDocument(reservation, roomType);
194	            emailService.sendConfirmationEmail(reservation.getGuestName(), reservation.getGuestEmail(), document);
195	
196	            ctx.json(reservation);
197	        } catch (NumberFormatException e) {
198	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
199	        }
200	    }
201	
202	    public void cancelReservation(Context ctx) {
203	        try {
204	            Long id = Long.parseLong(ctx.pathParam("id"));
205	            Reservation reservation = reservationRepository.findById(id);
206	
207	            if (reservation == null) {
208	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
209	                return;
210	            }
211	
212	            if (reservation.getStatus() != ReservationStatus.PENDING &&
213	                reservation.getStatus() != ReservationStatus.CONFIRMED) {
214	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Only pending or confirmed reservations can be cancelled"));
215	                return;
216	            }
217	
218	            reservation.setStatus(ReservationStatus.CANCELLED);
219	
220	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
221	                reservation.setRefund(reservation.getAmountPaid());
222	            } else {
223	                reservation.setRefund(BigDecimal.ZERO);
224	            }
225	
226	            reservationRepository.update(reservation);
227	
228	            ctx.json(reservation);
229	        } catch (NumberFormatException e) {
230	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
231	        }
232	    }
233	
234	    public void checkIn(Context ctx) {
235	        try {
236	            Long id = Long.parseLong(ctx.pathParam("id"));
237	            Reservation reservation = reservationRepository.findById(id);
238	
239	            if (reservation == null) {
240	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
241	                return;
242	            }
243	
244	            if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
245	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Only confirmed reservations can be checked in"));
246	                return;
247	            }
248	
249	            reservation.setStatus(ReservationStatus.CHECKED_IN);
250	            reservationRepository.update(reservation);
251	
252	            ctx.json(reservation);
253	        } catch (NumberFormatException e) {
254	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
255	        }
256	    }
257	
258	    public void checkOut(Context ctx) {
259	        try {
260	            Long id = Long.parseLong(ctx.pathParam("id"));
261	            Reservation reservation = reservationRepository.findById(id);
262	
263	            if (reservation == null) {
264	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
265	                return;
266	            }
267	
268	            if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
269	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Only checked-in reservations can be checked out"));
270	                return;
271	            }
272	
273	            reservation.setStatus(ReservationStatus.CHECKED_OUT);
274	            reservationRepository.update(reservation);
275	
276	            RoomType roomType = reservationRepository.getRoomType(reservation.getRoomNumber());
277	            Document document = DocumentService.generateDocument(reservation, roomType);
278	
279	            ctx.json(document);
280	        } catch (NumberFormatException e) {
281	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
282	        }
283	    }
284	
285	    public void getDocument(Context ctx) {
286	        try {
287	            Long id = Long.parseLong(ctx.pathParam("id"));
288	            Reservation reservation = reservationRepository.findById(id);
289	
290	            if (reservation == null) {
291	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
292	                return;
293	            }
294	
295	            if (reservation.getStatus() == ReservationStatus.PENDING ||
296	                reservation.getStatus() == ReservationStatus.CANCELLED) {
297	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
298	                return;
299	            }
300	
301	            RoomType roomType = reservationRepository.getRoomType(reservation.getRoomNumber());
302	            Document document = DocumentService.generateDocument(reservation, roomType);
303	
304	            ctx.json(document);
305	        } catch (NumberFormatException e) {
306	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
307	        }
308	    }
309	
310	    private boolean validateRequest(CreateReservationRequest request, Context ctx) {
311	        if (request.getRoomNumber() == null || request.getGuestName() == null ||
312	            request.getGuestEmail() == null || request.getCheckIn() == null ||
313	            request.getCheckOut() == null || request.getGuests() == null ||
314	            request.getRatePlan() == null) {
315	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
316	            return false;
317	        }
318	        return true;
319	    }
320	
321	    private boolean validateIdentification(CreateReservationRequest request, Context ctx) {
322	        boolean hasCpf = request.getGuestCpf() != null;
323	        boolean hasCnpj = request.getCompanyCnpj() != null || request.getCompanyName() != null;
324	        boolean hasPassport = request.getGuestPassport() != null || request.getGuestCountry() != null;
325	
326	        int identificationCount = 0;
327	        if (hasCpf) identificationCount++;
328	        if (hasCnpj) identificationCount++;
329	        if (hasPassport) identificationCount++;
330	
331	        if (identificationCount != 1) {
332	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Exactly one identification method required"));
333	            return false;
334	        }
335	
336	        if (hasCnpj && (request.getCompanyCnpj() == null || request.getCompanyName() == null)) {
337	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Both CNPJ and company name are required"));
338	            return false;
339	        }
340	
341	        if (hasPassport && (request.getGuestPassport() == null || request.getGuestCountry() == null)) {
342	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Both passport and country are required"));
343	            return false;
344	        }
345	
346	        return true;
347	    }
348	
349	    private void calculatePrices(Reservation reservation, Room room) {
350	        int nights = (int) reservation.getCheckIn().datesUntil(reservation.getCheckOut()).count();
351	        reservation.setNights(nights);
352	
353	        BigDecimal subtotal = BigDecimal.ZERO;
354	        LocalDate currentNight = reservation.getCheckIn();
355	
356	        for (int i = 0; i < nights; i++) {
357	            BigDecimal nightPrice = PricingService.calculateNightPrice(room.getNightlyRate(), currentNight);
358	            subtotal = subtotal.add(nightPrice);
359	            currentNight = currentNight.plusDays(1);
360	        }
361	
362	        subtotal = PricingService.round(subtotal);
363	        reservation.setSubtotal(subtotal);
364	
365	        BigDecimal discount = BigDecimal.ZERO;
366	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
367	            discount = subtotal.multiply(new BigDecimal("0.15"));
368	            discount = PricingService.round(discount);
369	        }
370	        reservation.setDiscount(discount);
371	
372	        BigDecimal total = subtotal.subtract(discount);
373	        total = PricingService.round(total);
374	        reservation.setTotal(total);
375	    }
376	}

