155	import java.math.BigDecimal;
156	import java.math.RoundingMode;
157	import java.time.LocalDate;
158	import java.time.Month;
159	
160	public class PricingService {
161	
162	    public static boolean isHighSeason(LocalDate date) {
163	        int year = date.getYear();
164	        Month month = date.getMonth();
165	        int day = date.getDayOfMonth();
166	
167	        // Julho inteiro
168	        if (month == Month.JULY) {
169	            return true;
170	        }
171	
172	        // 15 de dezembro até fim de fevereiro
173	        if (month == Month.DECEMBER && day >= 15) {
174	            return true;
175	        }
176	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
177	            return true;
178	        }
179	
180	        return false;
181	    }
182	
183	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
184	        BigDecimal price = baseRate;
185	        if (isHighSeason(night)) {
186	            price = price.multiply(new BigDecimal("1.20"));
187	        }
188	        return round(price);
189	    }
190	
191	    public static BigDecimal round(BigDecimal value) {
192	        return value.setScale(2, RoundingMode.HALF_EVEN);
193	    }
194	}
